{
    "predictors": [
        {
            "name": "Earnings Stability",
            "construction": "Calculate the standard deviation of quarterly earnings per share (EPS) over the past 5 years.",
            "rationale": "Firms with stable earnings are perceived as less risky and might be undervalued by risk-averse investors.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Patent Growth Rate",
            "construction": "Compute the annualized growth rate of the number of patents filed in the past 3 years using company patent disclosures.",
            "rationale": "Firms with rapid innovation may capture future growth opportunities that are not yet fully priced into the stock.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Supply Chain Dominance",
            "construction": "Ratio of firm sales to supplier expenditure, calculated using industry input-output tables and firm sales data annually.",
            "rationale": "Firms that dominate their supply chains have pricing power and potential cost advantages.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Environmental Efficiency",
            "construction": "Total revenue per metric ton of carbon emissions, using firm-reported emissions data and financial statements annually.",
            "rationale": "More environmentally efficient firms may incur lower future regulatory and operational costs, leading to higher profitability.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Customer Concentration Risk",
            "construction": "Percentage of total sales attributed to the top 3 customers from annual reports.",
            "rationale": "Firms reliant on a few customers may face higher business risk, potentially leading to higher expected returns as compensation.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Insider Trading Intensity",
            "construction": "Aggregate dollar value of insider purchases minus sales over the past 12 months, scaled by market capitalization.",
            "rationale": "High insider buying may signal undervaluation or future positive developments not yet known to the market.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "R&D Expense Trajectory",
            "construction": "Slope of the linear regression of research and development (R&D) expenses over the past 8 quarters.",
            "rationale": "Increasing investment in R&D might indicate commitment to future growth and innovation.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Employee Retention Rate",
            "construction": "Annual employee retention rate derived from employee count data in financial statements.",
            "rationale": "High retention rates may reflect good management and employee satisfaction, which can drive long-term performance.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Operational Complexity",
            "construction": "Number of distinct business segments reported in financial statements.",
            "rationale": "More complex firms might face higher management challenges and risk, leading to higher expected returns.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Geographic Revenue Diversification",
            "construction": "Herfindahl-Hirschman Index of revenue distribution across different geographic regions from annual reports.",
            "rationale": "Firms with diversified revenue sources may be less affected by regional economic downturns, potentially leading to undervalued risk.",
            "higher_returns_for": "low values of the measure"
        }
    ]
}
